import React, { useEffect, useMemo, useState } from 'react';
import axios from 'axios';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';
const DAYS = [
  { value: 1, label: 'Thứ 2' },
  { value: 2, label: 'Thứ 3' },
  { value: 3, label: 'Thứ 4' },
  { value: 4, label: 'Thứ 5' },
  { value: 5, label: 'Thứ 6' },
  { value: 6, label: 'Thứ 7' },
  { value: 0, label: 'Chủ nhật' },
];
const SLOTS = [
  { key: '18:00', start_time: '18:00', end_time: '18:45', label: '18:00 - 18:45' },
  { key: '18:45', start_time: '18:45', end_time: '19:30', label: '18:45 - 19:30' },
  { key: '19:30', start_time: '19:30', end_time: '20:15', label: '19:30 - 20:15' },
  { key: '20:15', start_time: '20:15', end_time: '21:00', label: '20:15 - 21:00' },
];

const timeValue = value => String(value || '').substring(0, 5);
const schedulesOverlap = (a, b) => (
  String(a.day_of_week) === String(b.day_of_week) &&
  timeValue(a.start_time) < timeValue(b.end_time) &&
  timeValue(a.end_time) > timeValue(b.start_time)
);
const teacherMatchesSchedules = (teacher, schedules) => (
  schedules.every(schedule => !(teacher.schedules || []).some(busy => schedulesOverlap(schedule, busy)))
);
const availabilityMatchesSchedules = (teacher, schedules) => {
  const availability = teacher.availability || [];
  if (availability.length === 0 || schedules.length === 0) return false;
  return schedules.every(schedule => availability.some(slot => (
    String(slot.day_of_week) === String(schedule.day_of_week) &&
    timeValue(slot.start_time) === timeValue(schedule.start_time) &&
    timeValue(slot.end_time) === timeValue(schedule.end_time)
  )));
};

export default function StudentClassRegistration() {
  const [form, setForm] = useState({
    teacher_id: '',
    schedules: [{ day_of_week: '1', start_time: '18:00', end_time: '18:45' }],
    note: '',
  });
  const [teachers, setTeachers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState(null);

  useEffect(() => {
    axios.get(`${API}/student/teachers`)
      .then(r => setTeachers(r.data.teachers || []))
      .catch(() => setMsg({ ok: false, text: 'Không tải được danh sách giáo viên' }))
      .finally(() => setLoading(false));
  }, []);

  const set = (key, value) => setForm(prev => ({ ...prev, [key]: value }));
  const setScheduleDay = (index, value) => {
    setForm(prev => ({
      ...prev,
      schedules: prev.schedules.map((schedule, i) => (
        i === index ? { ...schedule, day_of_week: value } : schedule
      )),
    }));
  };
  const setScheduleSlot = (index, slotKey) => {
    const slot = SLOTS.find(item => item.key === slotKey) || SLOTS[0];
    setForm(prev => ({
      ...prev,
      schedules: prev.schedules.map((schedule, i) => (
        i === index ? { ...schedule, start_time: slot.start_time, end_time: slot.end_time } : schedule
      )),
    }));
  };
  const addSchedule = () => {
    setForm(prev => ({
      ...prev,
      schedules: prev.schedules.length >= 2
        ? prev.schedules
        : [...prev.schedules, { day_of_week: '1', start_time: '18:00', end_time: '18:45' }],
    }));
  };
  const removeSchedule = (index) => {
    setForm(prev => ({
      ...prev,
      schedules: prev.schedules.length > 1
        ? prev.schedules.filter((_, i) => i !== index)
        : prev.schedules,
    }));
  };

  const availableTeachers = useMemo(() => (
    teachers
      .filter(teacher => teacherMatchesSchedules(teacher, form.schedules))
      .filter(teacher => availabilityMatchesSchedules(teacher, form.schedules))
  ), [teachers, form.schedules]);

  useEffect(() => {
    if (form.teacher_id && !availableTeachers.some(teacher => String(teacher.id) === String(form.teacher_id))) {
      set('teacher_id', '');
    }
  }, [availableTeachers, form.teacher_id]);

  const save = async () => {
    if (form.schedules.length === 0) {
      return setMsg({ ok: false, text: 'Vui lòng chọn lịch học' });
    }
    setSaving(true);
    setMsg(null);
    try {
      await axios.post(`${API}/student/class-registration`, form);
      setMsg({ ok: true, text: 'Đã gửi yêu cầu đăng ký lớp cho admin' });
    } catch (e) {
      setMsg({ ok: false, text: e.response?.data?.message || 'Lỗi gửi yêu cầu đăng ký lớp' });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="s-page">
      <h1 className="s-page-title">Đăng ký lớp</h1>
      <p className="s-page-sub">Chọn lịch học và giáo viên mong muốn, admin sẽ nhận thông báo để sắp xếp lớp cho bạn.</p>

      {msg && <div className={`s-form-msg ${msg.ok ? 'success' : 'error'}`}>{msg.text}</div>}

      <div className="s-register-card">
        <div className="s-register-grid">
          <div className="s-register-field full">
            <div className="s-register-row-head">
              <label>Lịch học mong muốn</label>
              <button type="button" className="s-mini-btn" onClick={addSchedule} disabled={form.schedules.length >= 2}>
                + Thêm buổi
              </button>
            </div>
            <div className="s-register-schedules">
              {form.schedules.map((schedule, index) => (
                <div className="s-register-schedule-row" key={index}>
                  <select value={schedule.day_of_week} onChange={e => setScheduleDay(index, e.target.value)}>
                    {DAYS.map(day => <option key={day.value} value={day.value}>{day.label}</option>)}
                  </select>
                  <select value={timeValue(schedule.start_time)} onChange={e => setScheduleSlot(index, e.target.value)}>
                    {SLOTS.map(slot => <option key={slot.key} value={slot.key}>{slot.label}</option>)}
                  </select>
                  <button type="button" className="s-mini-danger" onClick={() => removeSchedule(index)} title="Xoa buoi">
                    x
                  </button>
                </div>
              ))}
            </div>
          </div>

          <div className="s-register-field full">
            <label>Giáo viên mong muốn</label>
            <select value={form.teacher_id} onChange={e => set('teacher_id', e.target.value)} disabled={loading}>
              <option value="">{loading ? 'Đang tải giáo viên...' : 'Để admin sắp xếp hoặc chọn giáo viên phù hợp'}</option>
              {availableTeachers.map(teacher => (
                <option key={teacher.id} value={teacher.id}>{teacher.full_name}</option>
              ))}
            </select>
            {!loading && availableTeachers.length === 0 && (
              <small>Chưa có giáo viên phù hợp lịch này. Bạn vẫn có thể gửi để admin sắp xếp.</small>
            )}
          </div>

          <div className="s-register-field full">
            <label>Ghi chú</label>
            <textarea value={form.note} onChange={e => set('note', e.target.value)} rows={3} placeholder="VD: Em muốn học giao tiếp, ưu tiên lớp tối..." />
          </div>
        </div>

        <div className="s-register-footer">
          <span>Tối đa 2 buổi/tuần, dùng 4 khung giờ cố định của trung tâm.</span>
          <button className="s-btn-primary" onClick={save} disabled={saving}>
            {saving ? 'Đang gửi...' : 'Gửi đăng ký lớp'}
          </button>
        </div>
      </div>
    </div>
  );
}
